			return writeJSON(cmd, report)
		}
		out := cmd.OutOrStdout()
		fmt.Fprintln(out, report.Summary)
		for _, f := range findings {
			fmt.Fprintf(out, "\n  [%s] %s\n    %s:%d\n    %s\n    evidence: %s\n",
				strings.ToUpper(f.Severity), f.Title, f.File, f.Line, f.Detail, f.Evidence)
